/* The source 3D renders each sit on a much larger transparent canvas than
   their visible subject, so displaying them at "true" size makes them read
   as tiny. CroppedImg draws the image oversized inside a clipped box so the
   subject itself fills the box, instead of the padding. */
function CroppedImg({
  src,
  alt,
  size,
  scale = 1.2,
  overflow = "hidden",
  style,
  imgStyle,
}: {
  src: string;
  alt: string;
  size: number | string;
  scale?: number;
  overflow?: React.CSSProperties["overflow"];
  style?: React.CSSProperties;
  imgStyle?: React.CSSProperties;
}) {
  return (
    <span
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        width: size,
        height: size,
        overflow,
        flexShrink: 0,
        ...style,
      }}
    >
      <img
        src={src}
        alt={alt}
        draggable={false}
        style={{
          width: `${scale * 100}%`,
          height: `${scale * 100}%`,
          objectFit: "contain",
          ...imgStyle,
        }}
      />
    </span>
  );
}

function FloatIcon({
  spec,
  isSmall,
  index,
}: {
  spec: FloatSpec;
  isSmall: boolean;
  index: number;
}) {
  if (spec.hideOnSmall && isSmall) return null;
  const isDot = spec.shape === "dot";
  const common: React.CSSProperties = {
    position: "absolute",
    top: spec.top,
    left: spec.left,
    width: spec.size,
    animation: `${isDot ? "catonahat-float-dot" : "catonahat-float-object"} ${spec.duration}s ease-in-out ${spec.delay}s infinite`,
    animationDirection: index % 2 === 0 ? "normal" : "reverse",
    pointerEvents: "none",
    willChange: "transform, opacity",
    transformOrigin: "50% 50%",
  };

  if (isDot) {
    return (
      <div
        style={{
          ...common,
          height: spec.size,
          borderRadius: "9999px",
          background: `radial-gradient(circle at 34% 30%, #ffffff, ${spec.color})`,
          boxShadow: `0 3px 14px ${spec.color}99`,
          opacity: 0.94,
        }}
      />
    );
  }

  return (
    <div style={{ ...common, height: spec.size }}>
      <CroppedImg
        src={spec.img!}
        alt=""
        size="100%"
        scale={1.3}
        overflow="visible"
        imgStyle={{
          filter: "drop-shadow(0 9px 16px rgba(0,0,0,0.30))",
          opacity: 0.99,
        }}
      />
    </div>
  );
}

function FloatingField({ isSmall }: { isSmall: boolean }) {
  return (
    <div aria-hidden style={{ position: "absolute", inset: 0, overflow: "hidden", zIndex: 1 }}>
      {FLOATERS.map((f, i) => (
        <FloatIcon key={i} spec={f} isSmall={isSmall} index={i} />
      ))}
    </div>
  );
}

