/* ------------------------------ Modal --------------------------------- */

function getModalVisual(label: string) {
  const key = label.toLowerCase();
  if (key.includes("digital") || key.includes("product"))
    return { img: BAG_IMG, scale: 1.16, accent: ACCENTS.blue };
  if (key.includes("physical") || key.includes("shop"))
    return { img: GIFT_PINKTEAL_IMG, scale: 1.12, accent: ACCENTS.pink };
  if (key.includes("freebie"))
    return { img: TICKET_IMG, scale: 1.3, accent: ACCENTS.mint };
  if (key.includes("experiment"))
    return { img: FLASK_IMG, scale: 1.48, accent: ACCENTS.lavender };
  if (key.includes("curated"))
    return { img: STAR_PINK_IMG, scale: 1.38, accent: ACCENTS.pinkStrong };
  if (key.includes("today") || key.includes("drop"))
    return { img: FLOAT_GIFT_IMG, scale: 1.28, accent: ACCENTS.mint };
  if (key.includes("about"))
    return { img: FLOAT_PLANET_IMG, scale: 1.24, accent: ACCENTS.yellow };
  if (key.includes("explore"))
    return { img: FLOAT_CUBE_IMG, scale: 1.22, accent: ACCENTS.lavender };
  return { img: STAR_PINK_IMG, scale: 1.34, accent: ACCENTS.pink };
}

